approaches.phase-window-and-role:
"""A card sits inside its phase, and a pre-launch card says so (approach phase-window-and-role)."""
import re

PUBLISHING = re.compile('\\b(?:introduc\\w*|publish\\w*|go(?:es)? live|launch(?:es|ing)?(?! moment)\\b)', re.I)
PRELAUNCH = re.compile('unpromoted.*until the Launch moment in Month \\d+', re.I)


def span(months):
    nums = [int(n) for n in re.findall(r"\d+", str(months))]
    return (nums[0], nums[-1]) if nums else (1, 12)


def apply(case):
    pack = case["pack"]
    spans = {row.get("phase"): span(row.get("months")) for row in pack.get("phases") or []}
    for index, card in enumerate(pack.get("activation_cards") or []):
        name = card.get("name"); phase = card.get("phase"); month = card.get("month")
        low, high = spans.get(phase, (1, 12))
        if not low <= int(month) <= high:
            raise ValueError(
                f"tactical_roadmap_card_outside_phase: activation_cards[{index}] ({name}) sits in "
                f"Month {month} but its phase {phase} spans Months {low}-{high} -- move the card "
                "or its phase."
            )
        idea = str(card.get("idea") or "")
        text = idea + " " + str(card.get("desired_outcome") or "")
        if phase == "Pre-Seed" and PUBLISHING.search(idea) and not PRELAUNCH.search(text):
            raise ValueError(
                f"tactical_roadmap_prelaunch_role_unstated: activation_cards[{index}] ({name}) is a "
                "Pre-Seed card that introduces, launches or publishes -- state its pre-launch role: "
                "'live, unpromoted, until the Launch moment in Month N'."
            )
    return {"refusal": None, "rendered": "", "pack": pack}

